insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 1, 'A design sheet describes the loop predictCard returns as the well''s dynamometer card. What is wrong with that description?', '["The loop is a pump card rather than a surface card, and only the pump card can be compared with a measurement.", "The loop is a surface card and a measured card is a pump card, so the two are the same curve read at opposite ends of the string.", "Nothing on the loop was recorded at a well, since it is what a damped wave equation drew after being handed a fluid load, a surface motion and a typed damping ratio.", "The description is exact, because the package validates predictCard against measured cards through the diagnostic path."]'::jsonb, 2, 'The package holds a second solver, diagnoseCard, which propagates the harmonics of a card that was measured, and the two share no code path at all.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 2, 'ODUMA-4 marches 6110 steps in a cycle and the returned card carries 186 points at a stride of 33. What is one of those 186 points?', '["Every thirty third recorded step of the march, kept while the rest were discarded.", "An average of the 33 marched steps that fall inside it, which is why a decimated card is smooth.", "A crank angle sample, one for every two degrees of the revolution the four-bar was walked through.", "An interpolation onto an even grid of position, so the loop closes on itself."]'::jsonb, 0, 'The card keeps 3.044190 percent of the steps the march computed, and the discarded steps are gone from the returned object.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 3, 'The tension envelope in the same return object is built differently from the card. How?', '["It is decimated at the same stride of 33 and then interpolated onto the 120 node grid.", "It is recomputed from the returned card after the march finishes, which is why the two always agree.", "It keeps only the maximum tension at each node, since a minimum cannot be accumulated over a running march.", "It is accumulated over all 6110 steps at all 120 interior nodes and is never decimated."]'::jsonb, 3, 'Node spacing on the default grid is 40.000000000 ft, so the shallowest sample sits at 20.000000000 ft and the deepest at 4780.000000 ft.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 4, 'predictCard accepts cardSamples with a default of 180 and nodes with a default of 120. What can a studio user do with them?', '["Raise them for a final design and leave them at the defaults for a screening run, which is what the defaults are for.", "Nothing, because runRodPumpDesign forwards neither one and does not report which resolution the answer came off.", "Read them back from the returned object, since the stride of 33 and the 186 points are reported and the two imply the setting.", "Set them through maxCycles and tol, the other two parameters, which control the same sampling by another route."]'::jsonb, 1, 'The resolution of the answer was chosen for the caller, and the function does not say so.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 5, 'A caller asks for a march at a damping ratio of 0. What comes back?', '["A card with a notPeriodic warning attached, since an undamped string is exactly the case that flag exists for.", "A card marched to the maxCycles limit of 20, with converged returning false.", "A refusal, with a message saying the string never settles into a repeating stroke and that field strings sit between about 0.05 and 0.15 of critical.", "A card identical to the damped one, because damping enters as a coefficient rather than as a friction model."]'::jsonb, 2, 'The message names the range the caller was probably reaching for, and the two published runs at a damping ratio of 0.1 settle after 3 cycles with no warnings.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 6, 'A measured card of twelve samples is handed to the diagnostic. What happens?', '["It is padded to sixteen samples and propagated, with a warning attached to the result.", "It is refused, because there is nothing to propagate.", "It is propagated with as many harmonics as twelve points allow, which is four.", "It is passed to predictCard instead, which does not need a measured card at all."]'::jsonb, 1, 'A card with fewer than sixteen samples is one of the eight conditions that return nothing at all.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 7, 'The published taper is crossed by its own wave 195.465131814 times per stroke at 0.5 spm and 6.515504394 times at 15.0 spm. What changed between those two rows?', '["Only the stroke period, since the one way transit of 0.306960118 s and the round trip of 0.613920237 s belong to the string and the wave speed.", "The wave speed, which falls as the unit is driven harder and the string spends more of the cycle in tension.", "The length the wave has to cross, because a faster unit stretches the string further and lengthens the path.", "Both the transit time and the period, which is why the count falls by so much more than the speed rose."]'::jsonb, 0, 'At two hundred crossings a stroke every point of the string has heard about the surface motion long before it finishes, and that string is behaving as a spring.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 8, 'The published taper marches 11728 steps in a cycle at 5 spm and 6516 at 9 spm. Why does the slower run take more steps?', '["The slower run needs more cycles to settle, and every extra cycle adds its steps to the count.", "The engine holds the number of card points at 181 and adjusts the marched steps to reach it.", "A slower march is a stiffer problem, so the engine shortens the step to keep the answer stable.", "The step is set by the wave rather than by the operator, so it stays near 1.023192e-3 s while the cycle gets longer."]'::jsonb, 3, 'Both steps are tied to the fastest section wave speed of 16288.760984 ft/s, and 1.023123e-3 s at 9 spm is barely different from the slower one.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 9, 'The damping coefficient kappa comes back as 1.023453037 per s on the published taper at 5 spm and at 9 spm alike. What does that say about how damping was modelled?', '["It says the damping ratio of 0.1 was applied to the fastest section wave speed of 16288.760984 ft/s, which does not change with the pumping speed either.", "It says the two runs settled after the same 3 cycles, which is what kappa is accumulated over.", "It is built from the damping ratio and the string rather than from the motion, so it is a coefficient and not a friction model.", "It says the coefficient is capped, and a faster unit would drive it above the value the engine allows."]'::jsonb, 2, 'Fluid friction on the plunger, valve slippage and rod on tubing wear are not in the march at any setting.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 10, 'Away from the two transfers the ODUMA-4 pump load takes exactly two values. Which, and what are the two vertical sides of the parallelogram?', '["The peak and minimum polished rod loads of 19545.877783339 lb and 2625.472705679 lb carried down the string unchanged, and the sides are the top and the bottom of the 106.687716837 in surface stroke.", "4690.299657039 lb while it lifts and 0 lb while it falls, and the sides are the transfers, where the plunger is held still while the rod above it stretches or relaxes.", "The fluid load and the buoyed weight of 9466.342675159 lb, and the sides are where the travelling and standing valves are both shut.", "The full fluid load and a negative value of the same size, and the sides are where the plunger reverses direction."]'::jsonb, 1, 'The full fluid load of 4690.299657039 lb is the same number the pump calculation produced from a differential and an area.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 11, 'The ODUMA-4 surface card encloses 750654.615621 in-lb per cycle and the pump card 413225.894771 in-lb per cycle. What is the 337428.720850 in-lb per cycle between them?', '["The work the rods and the damping absorb between the two ends of the string.", "The work the counterbalance returns to the gearbox over the downstroke, which the surface card includes and the pump card does not.", "The error the decimation introduces, since both areas are read off cards of 186 points and the surface loop is the longer of the two.", "The energy stored in the string as static stretch, which is 15.535532787 in of travel times the fluid load."]'::jsonb, 0, 'A card area is a closed loop of load against position, so the difference between the two loops is what was spent between them.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 12, 'What does a predicted card actually claim?', '["That the loads on it are within the ratings of the unit, since a card that overloaded the structure would raise a warning instead.", "That the assumed damping ratio was the right one, because a wrong ratio would not have settled at all.", "That this string, driven this way, settles into this loop, which ODUMA-4 reports after 4 cycles and the published runs after 3.", "That the plunger stroke of 98.526653100 in is what the barrel saw, which is the one figure a card is a measurement of."]'::jsonb, 2, 'Without a settled cycle the loop is one transient among many and none of its extremes mean anything.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 13, 'A predicted card from this engine will never look like a gas interference card. Why not?', '["The fillage input already accounts for gas, so an interference card is folded into the fillage the caller typed.", "Gas interference shows only on a measured card, and the diagnostic is the path that reads those.", "The engine refuses a design in which free gas would reach the pump, so the case never arrives at the march.", "No term in the march can produce one."]'::jsonb, 3, 'Rod buckling, tubing movement, plunger friction, deviated hole side loading and gearbox losses are all outside the model as well, and silence about them is not approval.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 14, 'notPeriodic, structuralOverload and incompleteFillage are warnings while a linkage that does not close is a refusal. What is the difference in what comes back?', '["A warning is raised by the march and a refusal by the input checks, so a refusal is always known before the march starts and names the input it read.", "A warning arrives attached to a full result that still looks complete and confident, while a refusal returns no answer at all.", "A warning sets ok false with the result still populated, and a refusal empties the result and sets ok false as well, so the flag alone cannot separate them.", "A warning can be cleared by rerunning at a finer resolution, and a refusal cannot be cleared at all."]'::jsonb, 1, 'Eight conditions refuse and eight codes warn, and reading a design with no warnings as approved is the mistake the split exists to prevent.'),
  ('rodpump', 'intermediate', 'module', 'm01-the-card-is-the-design', 15, 'The highest load on the ODUMA-4 card is 19545.877783339 lb at point 29 of 186 and the lowest is 2625.472705679 lb at point 134. What are those two numbers?', '["The extremes of the decimated card, which is what prlPeakLb and prlMinLb report.", "The extremes of the tension envelope at the shallowest node, which the design also uses for its section stresses.", "The extremes of the march, taken over all 6110 steps before the card was cut down to 186 points.", "The extremes of the pump card, carried up to the surface by adding the buoyed weight of the string."]'::jsonb, 0, 'They come off the 3.044190 percent of the march that survived the decimation, at cycle fractions 0.151227 and 0.718331.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 1, 'rodStretchIn returns 3.744037060 in for the published taper under 1000.0 lb and 18.720185299 in under 5000.0 lb. What is the calculation behind those two numbers?', '["A march of the load down the string section by section, adding the stretch each section takes at its own area before the next one is loaded.", "The elastic constant Er times the load, and nothing else, which is why the answer is linear in the load.", "The load divided by the spring rate of the shallowest section, since the top of the string carries every pound the pump hangs on it.", "The compliance of the string times the load times a dynamic factor built from the pumping speed, which is what makes the stretch a running quantity."]'::jsonb, 1, 'Er is the sum of length over area for every section divided by Young''s modulus, so it is fixed by the steel and the geometry and the multiplication carries no memory of how fast the load arrived.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 2, 'The published uniform string stretches 3.925786432 in per 1000 lb and the published taper 3.744037060 in. Why is the uniform string the stretchier of the two?', '["Because a uniform string has no step in area, and a step is what stops a stretch propagating past it into the section below.", "Because 7/8 rod is more compliant per foot than 3/4 rod, so a string made entirely of the larger size gives up more length under the same load.", "Because the taper is designed on stress, and a string designed on stress is stiffer per foot than one designed on weight at every point along it.", "Mostly because it is a thousand feet longer, at 6000 ft against 5000 ft."]'::jsonb, 3, 'ODUMA-4 is shorter still at 4800 ft and stretches least of the three at 3.312268708 in per 1000 lb, so the ranking follows the length before it follows anything else.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 3, 'ODUMA-4 opens with 1500 ft of 1 in rod, the shortest of its three runs, and that section carries 22.685963 percent of the whole string compliance. What does that share say?', '["Thick rod is stingy with compliance, so the section that is shortest and largest contributes least of what the string gives up.", "The section is carrying 22.685963 percent of the buoyed weight, since compliance and weight are the same share taken twice.", "The section stretches 22.685963 percent as far as the string does, because a share of compliance is a share of travel.", "The engine has weighted the section by its length over the total 4800 ft, and 1500 ft of 4800 ft is close enough to that share to be the same thing."]'::jsonb, 0, 'Compliance is what adds in series, and the 3/4 section at the bottom carries 45.708015 percent of it on a string whose Er is 3.312268708 in/lb.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 4, 'Hand rodStretchIn the same load at 0.5 spm and at 15.0 spm. What comes back?', '["A longer stretch at the faster speed, since the inertia of the rods below adds to the load the string is asked to carry.", "A shorter stretch at the faster speed, with less of the cycle in which to give up length.", "The same inches at both speeds, because there is no term for time, mass or speed in the expression.", "A refusal at 15.0 spm, since the static form is not valid once the wave crosses the string fewer than ten times in a stroke."]'::jsonb, 2, 'It also assumes the load is applied at the pump, so a load distributed along the string does not stretch it by this amount either.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 5, 'What does the spring rule compute, and out of what?', '["The plunger stroke, as the surface stroke times the ratio of the plunger area to the rod area at the pump end of the string.", "The plunger stroke, as the surface stroke less the static stretch under the fluid load, written S less Fo Er.", "The static stretch, as the plunger stroke subtracted from the surface stroke once the march has returned the first of the two.", "The surface stroke the linkage has to deliver if the plunger is to travel a stated distance, which is the four-bar sizing problem run backwards."]'::jsonb, 1, 'On the published taper that is 64.000000 in less 18.720185299 in, which is 45.279814701 in, and on ODUMA-4 it is 106.687716837 in less 15.535532787 in, which is 91.152184050 in.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 6, 'Walk the fluid load on the published taper from 1000.0 lb to 5000.0 lb. What does the spring rule do?', '["It falls in a straight line from 60.255962940 in to 45.279814701 in, 3.744037060 in of plunger stroke lost per 1000 lb.", "It falls faster than a straight line, because a heavier column stretches the shallow sections into a range where the steel is less stiff.", "It falls and then flattens, since a fluid load past 4000.0 lb is carried increasingly by the tubing instead of by the rods.", "It does not move, since the fluid load enters the march rather than the closed form, which is speed free."]'::jsonb, 0, 'The fluid load is the only lever in the expression, so a heavier column, a larger plunger and a deeper fluid level all arrive through the same term.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 7, 'At 0.5 spm the published taper marches to 45.286791250 in against the spring rule''s 45.279814701 in. Why is that row the one the engine''s own test suite gates?', '["It is the fastest row the closed form is valid at, so the gate is checking the top of the range where the rule may still be used.", "It is the row where the two solvers, the engine and the oracle, are furthest apart, so it bounds the disagreement between the routes.", "It is the only row in the ladder where the march converges, so it is the only one that can carry a gate at all.", "It is the static limit, where the two rules have to agree, and the gate requires the marched answer within one percent of the rule."]'::jsonb, 3, 'The gap there is 0.006976549 in, or 0.015408 percent, and a build that misses the static identity is wrong before any dynamic number is read.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 8, 'The spring rule is applied to a design at 9 spm, where the wave crosses the string 10.859173990 round trips per stroke. What does the returned number look like?', '["Obviously wrong, since the rule returns a plunger stroke longer than the surface stroke once the string stops behaving as a spring.", "Flagged, because the closed form checks the speed against the string fundamental before it returns.", "Plausible, shorter than the surface stroke and carrying nothing that says it was applied outside the conditions where it holds.", "Unavailable, since the rule is evaluated inside the march and a running design returns the marched stroke in its place."]'::jsonb, 2, 'It always returns a number and it never says which conditions it assumed, which is why the 0.5 spm row at 195.465131814 round trips and the 9 spm row at 10.859173990 are told apart by the reader and not by the function.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 9, 'The marched plunger stroke is longer than the spring rule at every speed on the published taper. What is the mechanism?', '["The rods below the polished rod still have momentum when it reverses, and the static rule has no term for mass.", "The march applies the fluid load over the whole cycle while the closed form applies it only on the upstroke, so the marched stretch is smaller.", "The damping ratio adds travel to the plunger, which is why the marched answer grows with the damping the caller types.", "The plunger stroke is read off the decimated card, and a decimated peak to trough is the wider one."]'::jsonb, 0, 'That is why the overtravel is 0.015408 percent at 0.5 spm and 17.144281 percent at 15.0 spm on the same string: it is inertia, and inertia is what a slow stroke does not have.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 10, 'On the published taper the overtravel runs 4.403772 percent at 6.0 spm, 0.738434 at 7.0 and 3.910776 at 8.0. What should be made of the row that steps back?', '["It is round off in the reported figure, so the three rows should be smoothed before any of them is quoted.", "It is a real feature of the march: the settled cycle depends on where the valve transfers fall against the wave arriving back from the pump, and that phase is not smooth in speed.", "It is the row where the march failed to converge, which is why its overtravel falls out of line with its neighbours.", "It is the speed at which the string passes through a resonance, and a resonance narrows the plunger travel as it is crossed."]'::jsonb, 1, 'Overtravel grows in the large, from 0.015408 percent to 17.144281 percent, and does not grow in the small, so three rising rows are never a trend.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 11, 'Walking the fluid load on the published taper at 9 spm gives an overtravel of 3.020373 percent at 1000.0 lb, 9.696181 at 5000.0, 12.785687 at 7000.0 and 6.280545 at 8000.0. What does that sequence support?', '["Nothing, since the last two rows fall and a hypothesis that fails on two rows out of eight has been refuted.", "That overtravel is proportional to the fluid load, which is the closed form the ladder was run to fit.", "That the fluid load moves the marched stroke while leaving the spring rule where it was, so the whole column is the march moving alone.", "The inertia reading in the large, since a heavier load on the same stiffness overtravels more, with the top of the sweep breaking the trend."]'::jsonb, 3, 'The percentage is the column to read because the fluid load moves the spring rule too, and the stall at 7000.0 lb and the collapse at 8000.0 lb are the same phase effect that makes the speed ladder ragged.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 12, 'At 9 spm the oracle returns a plunger stroke of 49.864170826 in and the engine 49.670227367 in, while the spring rule returns 45.279814701 in. What does that comparison establish?', '["That the engine is 0.388944 percent low and its overtravel should be corrected upward by that amount before it is reported.", "That the oracle and the engine disagree by more than the gates allow, so neither stroke can carry a claim about overtravel at this speed.", "That the overtravel is physics rather than scheme error, since two independent numerical routes sit 0.388944 percent apart while the rule sits 9.696181 percent from both.", "That the spring rule is the average of the two marched answers, which is what makes it a usable check on either one."]'::jsonb, 2, 'The oracle marches a staggered grid with RK4 on velocity and tension and the engine marches displacement on a collocated grid with a central difference, so the two dispersion errors do not coincide.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 13, 'At 5 spm the engine sits 0.637731 percent from the oracle on plunger stroke and the overtravel at that speed is 0.373874 percent. What may be claimed from that row?', '["Nothing about overtravel, because the effect is smaller than the disagreement between the two routes that measure it.", "That the overtravel at 5 spm is 0.373874 percent, since it is the difference between two figures the engine itself returned consistently.", "That the engine understates overtravel at low speed, sitting below the oracle by more than the effect.", "That the oracle is the wrong reference here, since it was gated at 2 percent on plunger stroke and 5 spm is inside that band."]'::jsonb, 0, 'The oracle gates hold the two routes to 2 percent on plunger stroke, so an effect of 0.373874 percent is invisible to it by construction and the claim belongs to the 9 spm row instead.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 14, 'displacementBpd is fed a stroke. Which one, and why that one?', '["The spring rule stroke, because a volume should be built on a closed form rather than on a number sampled off a march.", "The marched stroke, because it is the travel the plunger makes inside the barrel and therefore the travel that sweeps volume.", "The surface stroke, since the rating the design reports is what the linkage delivers to the polished rod.", "The average of the two, which is what the dimensionless group Sp over S of 0.923505123 records for the design."]'::jsonb, 1, 'On ODUMA-4 the march returns 98.526653100 in against a surface stroke of 106.687716837 in, and Sp over S comes back as 0.923505123 on the marched figure.'),
  ('rodpump', 'intermediate', 'module', 'm02-stretch', 15, 'A design sheet for ODUMA-4 reports the spring rule''s 91.152184050 in as the plunger stroke instead of the marched 98.526653100 in. What follows?', '["Nothing downstream, since the rates are built from the surface stroke of 106.687716837 in and the plunger stroke is reported beside them.", "The loads move with it, because the peak and the minimum polished rod loads are read off the same stroke the volume is built on.", "Every barrel figure downstream inherits a stroke 7.374469050 in short, which is 8.090282 percent.", "A warning, since the design compares the closed form against the march and raises notPeriodic when the two disagree by more than one percent."]'::jsonb, 2, 'The rated 380.874258458 bbl/d, the swept 351.739329047 bbl/d and the produced 316.565396142 bbl/d stand on the marched stroke, and nothing in the return object would flag the substitution.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 1, 'prlPeakLb comes back as 19545.877783339 lb on ODUMA-4. What kind of quantity is it?', '["The buoyed weight plus the fluid load, which on this design is the sum a static string would hang on the polished rod at the top of the upstroke.", "The largest of the three section maximum loads the design reports, which on this design is the top section at 19800.044639 lb.", "A maximum taken over a curve, so it carries the damping ratio, the surface motion and the phase of the returning wave with it.", "A rating, since the peak is what structuralOverload compares against the capacity of the unit before the design is returned."]'::jsonb, 2, 'It is read at cycle fraction 0.151227 with the polished rod 27.960212851 in into its travel, and it is not a formula and not a sum of the loads that produced it.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 2, 'The oracle committed 15231.366293700 lb at 5 spm and 16545.574080121 lb at 9 spm, and the engine returns 15230.601238973 lb and 16490.601223060 lb. What do those two pairs show?', '["The peak is the best behaved of the three headline numbers, at -0.005023 percent on one run and -0.332251 percent on the other.", "The engine is biased low on peak load, and the bias grows with speed, so a working peak should be raised before use.", "The two routes disagree by more than the published gates allow at 9 spm, so the faster of the two runs cannot carry a peak load claim.", "The oracle is the finer scheme, since it marches a staggered grid with RK4 and returns the larger peak on both runs."]'::jsonb, 0, 'Two independent schemes, different unknowns and different integrators, and five thousandths of a percent apart at one speed and a third of a percent at the other.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 3, 'On the published taper the peak climbs from 13756.379902 lb at 0.5 spm to 18752.731892 lb at 15.0 spm without a single step back, while the plunger stroke off the same runs steps back six times. What does that pair of behaviours mean?', '["The plunger stroke is the unconverged one, since a quantity that steps back has not settled and the peak has.", "The peak is smooth because it is read off the card and the stroke is ragged because it is read off the tension envelope, which is a different sampling.", "The stroke is sampled at a coarser resolution than the peak, so its raggedness is decimation noise and the peak is the trustworthy one.", "One number out of a march can be smooth in an input while another out of the same march is not."]'::jsonb, 3, 'Both come out of one call on one march, so a claim about smoothness belongs to a named quantity and never to the solver.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 4, 'At 0.5 spm the published taper peaks at 13756.379902 lb against a buoyed rod weight plus fluid load of 13673.757962 lb. Why is that comparison worth making?', '["It shows the march is in error at the slow end, which is the numerical floor of the scheme.", "It is the static datum, so everything the peak stands above it at a working speed is dynamics.", "It shows the peak has converged, because a converged march returns the static sum exactly and an unconverged one does not.", "It is the sum structuralOverload is checked against, so a peak near it is a design at the limit of the unit that carries it."]'::jsonb, 1, 'At 9 spm the same string peaks 7816.843261277 lb above the buoyed weight of 8673.757961783 lb, and that distance is what the word dynamic means here.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 5, 'The minimum polished rod load is measured against a different datum from the peak. Which, and why?', '["Zero, because the minimum is the load at which the string would go slack, and a minimum is only meaningful as a margin above slack.", "The buoyed weight less the fluid load, since the column pushes up on the plunger through the whole of the downstroke.", "The buoyed rod weight alone, because the travelling valve opens on the downstroke and the fluid load transfers to the tubing.", "The same buoyed weight plus fluid load the peak uses, because both extremes are read off one card and a card has one datum."]'::jsonb, 2, 'At 0.5 spm the published taper bottoms at 8586.448887 lb against a buoyed weight of 8673.757961783 lb, and at 9 spm it sits 2850.547021552 lb below it.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 6, 'The published gates hold the two routes to 2 percent on plunger stroke and 3 percent on the minimum load. Why is the loosest gate in the suite on the minimum?', '["The minimum is the smallest of the three numbers, so the same absolute error is a larger percentage of it and the gate was widened to match.", "The minimum is read off the decimated card while the peak is read off the tension envelope, so only one of the two is a subsample.", "The oracle does not compute a minimum polished rod load directly, so its gate covers a quantity reconstructed from the card it returned.", "It is the hardest extreme for a scheme to land on, and the engine and the oracle sit 1.057795 percent apart on it at 5 spm against 0.005023 percent on the peak."]'::jsonb, 3, 'At 9 spm the two routes are 0.444034 percent apart on the minimum and 0.332251 percent apart on the peak, and the gate has to hold the worse of the runs.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 7, 'ODUMA-4 reports a minimum polished rod load of 2625.472705679 lb, comfortably in tension. What do the section loads from the same design say?', '["The bottom section runs to -1100.730218 lb and a minimum stress of -2491.543540 psi, so part of the string is in compression.", "They agree with it, since the reported minimum is the smallest load anywhere in the design and the sections are read from the same card.", "The middle section is the one in compression, at 67.196301 lb, because compression is reached first where the taper steps down.", "They cannot be compared, since the section figures are stresses in psi and the reported minimum is a load in lb."]'::jsonb, 0, 'The top section bottoms at 2331.994757 lb and the middle at 67.196301 lb, and the engine models no rod buckling and no sinker bar, so nothing in the result warns about the bottom one.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 8, 'The published taper returns 8038.598759155 lb of load range at 5 spm and 10667.390282828 lb at 9 spm. What made the range widen?', '["The peak alone, because the minimum is pinned to the buoyed weight of 8673.757961783 lb and a datum does not move with speed.", "Both ends of the card moved, since the peak climbed and the minimum fell over the same speed change.", "The minimum alone, because the peak is nearly the static sum of the rod weight and the fluid load at any speed on this string.", "Neither end, because the range is computed from the RP 11L groups F1 over Skr and F2 over Skr rather than from the two reported loads."]'::jsonb, 1, 'The range is the only one of the three headline numbers that collects both movements, and it is what the steel feels because steel fails on the swing rather than on the average.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 9, 'ODUMA-4 returns Skr of 32209.861648 lb, Fo over Skr of 0.145616883 and F1 over Skr of 0.312933201. What are those groups?', '["Measurements from the RP 11L test wells, carried into the design as published correlations of the dimensionless groups.", "Checks, since a design whose groups fall outside the published RP 11L range raises a warning and returns a partial result.", "The route by which the loads themselves are computed, so the reported peak and minimum are read back out of the groups and the load scale.", "Definitions, computed from the loads whatever route produced them."]'::jsonb, 3, 'Skr is the spring rate of the string times the surface stroke, and the groups are arithmetic on the loads rather than a second opinion about them.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 10, 'A report quotes the ODUMA-4 load range of 16920.405077660 lb and its worst section loading of 82.873308396 percent in one sentence, as though the second followed from the first. What is wrong with that?', '["The two are read off different samplings of one march, the range off the decimated card and the section loads off the tension envelope.", "Nothing, since both come out of one call on one design and describe the same settled cycle at the same speed.", "The percentage is against a modified Goodman allowable, so it should be compared with a stress range in psi rather than with a load range in lb.", "The load range is a surface number and the worst section is the top section at 20.000000 ft, so the two are only one node apart on the same string."]'::jsonb, 0, 'The section maxima and minima that feed the Goodman check are accumulated over every marched step, while the reported range is read off the 186 points the card kept.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 11, 'The ODUMA-4 load range runs 16157.838473 lb at a damping ratio of 0.0800 and 18689.749941 lb at 0.2000. What is that sweep moving?', '["The fluid load, since damping is applied to the column the plunger lifts and a heavier apparent column widens the card.", "The surface stroke, because a more heavily damped string cannot follow the four-bar and the polished rod travel shortens.", "An input nobody measures, which widens the range steadily across seven contiguous rows.", "The rod grade, since a damping ratio is a property of the steel and the fluid it moves in rather than of the design."]'::jsonb, 2, 'It is the one input on this page with no measurement behind it, and the engine''s own message puts field strings between about 0.05 and 0.15 of critical.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 12, 'Across the nine contiguous rows of the ODUMA-4 damping sweep the peak moves 2223.684206 lb and the minimum 2115.653830 lb. What else does the sweep show about the rows inside the field band?', '["Every row inside the band converges, and only the rows outside it raise notPeriodic, which is what makes the band a usable range.", "Three of them come back with notPeriodic and converged false, so the sweep is not clean over the band the engine''s own message calls the field range.", "The rows inside the band raise rodOverstressed instead, because a lightly damped string reaches a higher peak against the same allowable.", "The peak and the minimum move by the same amount on every row, which is what keeps the load range fixed across the band."]'::jsonb, 1, 'The plunger stroke moves 13.541308 in over the same nine rows, and tuning the damping ratio until the loads look right is the mistake that follows.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 13, 'Walk the ODUMA-4 plunger from 1.2500 in to 2.2500 in. The minimum load reads 3387.340512, 2676.609973, 2625.472706, 2605.335024 and 3489.805977 lb. What does that column do?', '["It falls across the first four rows and turns back up on the fifth, so a bigger plunger is not simply worse at both ends of the card.", "It falls throughout, since a larger plunger hangs a larger fluid load on the string and the downstroke unloads further each time.", "It tracks the peak, which climbs from 17041.875221 lb to 22756.352510 lb over the same five rows, because both ends move with the fluid load.", "It is flat within the resolution of the card, since the minimum is set by the buoyed weight and the plunger does not change the string."]'::jsonb, 0, 'Worst section loading walks 71.721589, 77.942485, 82.873308, 89.702671 and 102.235377 percent down the same rows, and the last one raises rodOverstressed.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 14, 'Taking ODUMA-4 from a fluid specific gravity of 0.7500 to 1.0500 moves the peak from 19750.187337 lb to 19341.568229 lb. What does the plunger stroke do over those seven rows?', '["It lengthens with the heavier fluid, since a larger buoyancy effect takes weight off the string and lets the plunger travel further.", "It shortens with the heavier fluid, because the fluid load rises with the specific gravity and a larger fluid load costs plunger stroke.", "It reads 98.526653 in on every one of them, because the fluid changes the weight the rod carries and not how far the string stretches under a given load.", "It moves by less than the reported figures resolve, so the column is flat only to the digits the design happens to print."]'::jsonb, 2, 'The buoyancy factor walks from 0.904458599 to 0.866242038 and the buoyed weight from 9670.652229 lb to 9262.033121 lb, and the spring rate and the elastic constant are properties of the steel and the geometry.'),
  ('rodpump', 'intermediate', 'module', 'm03-the-loads', 15, 'ODUMA-4 marches 6110 steps in a cycle and keeps 186 of them. What does that do to the reported peak and the reported minimum?', '["It leaves both untouched, since the decimation keeps every recorded step at which either extreme occurred.", "A maximum over a subsample can only be low and a minimum can only be high, so the reported range is narrowed at both ends and neither error is reported.", "It moves the minimum only, because the peak is also carried in the tension envelope and the design reports the envelope figure.", "It widens the reported range, because a coarse card exaggerates a turn and both extremes are turns in the curve."]'::jsonb, 1, 'The card keeps 3.044190 percent of the steps the march computed, the tension envelope keeps all of them at all 120 interior nodes, and runRodPumpDesign exposes neither cardSamples nor nodes.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 1, 'ODUMA-4 at 10 spm returns a card area of 750654.615621 in-lb per cycle and a polished rod horsepower of 18.955924637 hp. What produced the horsepower?', '["The fluid load of 4690.299657039 lb times the plunger stroke of 98.526653100 in times the speed, which is the rate at which the pump lifts the column.", "The peak polished rod load of 19545.877783339 lb times the surface stroke of 106.687716837 in times the speed, on the reasoning that a worst case load over a full stroke bounds the work.", "The card area times the pumping speed, over 396000.", "The pump card area of 413225.894771 in-lb per cycle times the speed over 396000, on the reasoning that only work reaching the fluid is power."]'::jsonb, 2, 'Nothing else enters it: not the rod weight, not the depth, not the plunger size, except through the card those things already produced.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 2, 'The two divisions in polished rod horsepower collapse into 396000. Which two?', '["12 in per ft, to turn in-lb into ft-lb, and 33000 ft-lb per minute per horsepower.", "The 12 in per ft that turns in-lb into ft-lb, and the minutes in a day, which is what puts the answer on the same time base as the 316.565396142 bbl/d the design reports.", "33000 ft-lb per minute per horsepower, and the 12 strokes a minute a beam unit is rated for.", "The 12 in per ft, and the plunger area of 2.405281875 in2."]'::jsonb, 0, 'The whole calculation is the card area times the speed over 396000, and 750654.615621 in-lb per cycle at 10 spm gives 18.955924637 hp.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 3, 'Take ODUMA-4 from 6.0 spm to 12.0 spm. The horsepower goes from 8.791354106 hp to what?', '["It doubles, because the speed multiplies a card area fixed by the string, the fluid load and the linkage stroke.", "13.295316471 hp, because the card area falls as the speed rises and takes back most of the multiplication the speed applied.", "It cannot be read off the sweep, because a design at twice the speed no longer returns a horsepower once it raises a warning.", "24.676711395 hp, well over double, because the card area grew from 580229.370988 to 814331.476024 in-lb per cycle underneath the multiplication."]'::jsonb, 3, 'The speed is in the answer twice, so a designer who prorated 8.791354106 hp would size surface equipment for a machine that does not exist.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 4, 'What quantity does the card area measure?', '["The work delivered to the fluid in one cycle, which is why dividing 750654.615621 in-lb per cycle by 316.565396142 bbl/d prices a barrel.", "The work the polished rod did in one cycle, as the area enclosed by a closed loop of load against position.", "The peak load of 19545.877783339 lb over the full 106.687716837 in of travel.", "The mean load over the loop times the plunger stroke of 98.526653100 in."]'::jsonb, 1, 'It is a shoelace integral around a loop that has to close, which is why the march runs until the cycle repeats, four cycles on ODUMA-4.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 5, 'The surface loop is integrated against the polished rod''s travel. Which travel is the pump loop integrated against, and what does owning both let a reader see?', '["The same 106.687716837 in of polished rod travel, since both loops come off one march and a card solver draws every loop it returns on the surface position axis.", "Crank angle through one revolution, since the pump loop is what the four-bar delivered at the bottom of the string and a torque factor is a function of angle.", "The plunger''s own 98.526653100 in, so the smaller loop is the work that survived the string, drawn against the travel the barrel actually saw.", "Time across the settled cycle, since the pump end has no position of its own until a plunger stroke has been read peak to trough off the node there."]'::jsonb, 2, 'The surface loop encloses 750654.615621 in-lb per cycle and the pump loop 413225.894771, and a shoelace integral is only as meaningful as the axis it was drawn on.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 6, 'The ODUMA-4 pump loop encloses 413225.894771 in-lb per cycle. Which product does that figure sit closest to?', '["The mean of the peak and the minimum polished rod loads over the plunger stroke of 98.526653100 in, since a pump loop is a surface loop with the rod weight taken off it.", "The fluid load over the whole 106.687716837 in surface stroke, since the load sits on the plunger for as long as the travelling valve stays shut against it.", "The buoyed weight of 9466.342675159 lb over the plunger stroke, since a card drawn at the pump is still drawn against the rods that carry the plunger.", "The fluid load carried through the plunger travel between the two valve transfers."]'::jsonb, 3, 'That loop is nearly a rectangle, which is what a load taking two values and a pair of vertical transfers make, and the surface loop it is compared with is not.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 7, 'The default card on the published taper reads 323421.9269 in-lb per cycle at 9 spm against 323838.0408 over every marched step, and loses only 63.3284 in-lb per cycle at 5 spm. What decides the size of that loss?', '["How sharply the real card turns, which is why the same default costs 0.128494 percent at one speed and 0.023711 percent at the other.", "The number of marched steps, 6516 against 11728, so the run that marched more steps has more of them to throw away.", "The card point count, which is 181 at 9 spm and falls with speed, leaving the faster run fewer points to integrate over.", "The decimation stride, 36 against 65, and a larger stride always costs a loop more of its area."]'::jsonb, 0, 'Same default and same string, and one costs several times the other. On ODUMA-4 the same default gives up 9148.2107 in-lb per cycle, which is 1.204024 percent.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 8, 'What does the polished rod horsepower refuse to be more exact than?', '["The damping ratio of 0.12, the one input nobody measures.", "The card it was handed, which keeps 186 of the 6110 steps the march computed on ODUMA-4.", "The plunger stroke of 98.526653100 in, because the area is integrated over the travel the barrel actually sees.", "The published gate of 2 percent on plunger stroke, which is the tightest tolerance any independent route holds this engine to."]'::jsonb, 1, 'That card''s area is 9148.2107 in-lb per cycle below the area over every marched step, which is 1.204024 percent, and the horsepower moves with it.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 9, 'ODUMA-4 reports 0.059879964 hp per bbl/d. What kind of number is that?', '["An energy cost per barrel, ready to be multiplied by a tariff.", "A property of the pump, so it carries to any well running the same 1.75 in plunger against the same 4690.299657039 lb of fluid load.", "A mechanical ratio at one point in the machine, on one design at one speed.", "A rating the engine checks the design against."]'::jsonb, 2, 'There is no tariff, no motor efficiency and no cost anywhere in the return object, so anything with currency in it is arithmetic done outside this engine.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 10, 'Walking ODUMA-4 from a damping ratio of 0.0500 to 0.2000 takes the horsepower from 15.588073 to 24.404568 hp while the production falls from 353.253676 to 309.745554 bbl/d. Why do both move against the design?', '["The extra damping raises the fluid load, so more work goes in per stroke.", "The extra damping shortens the surface stroke the four-bar delivers.", "The card area is fixed by the string, and the horsepower rises with the extra cycles a heavily damped run needs to settle, four on this design.", "More of the polished rod''s work goes into the string and less of the stroke reaches the plunger."]'::jsonb, 3, 'The price of a barrel rises at both ends of the fraction at once, on an input nobody measures and whose field range the engine''s own message puts between about 0.05 and 0.15 of critical.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 11, 'Three rows of the ODUMA-4 damping sweep inside the band the engine calls the field range come back flagged. What is the flag, and what does it do to the answer?', '["rodOverstressed, once the worst section loading passes 102.235377 percent.", "notPeriodic, with converged false, and the row still reports a full horsepower and a full produced rate.", "timestep, because a lightly damped string forces a shorter step.", "incompleteFillage, since a string that never settles into a repeating stroke cannot fill a barrel at the stated fillage of 0.9."]'::jsonb, 1, 'A warning means an answer was produced anyway, so 15.588073 hp and 353.253676 bbl/d come back looking exactly as confident as the rows that converged.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 12, 'Which lever actually buys barrels cheaply in horsepower on ODUMA-4?', '["The plunger, since 1.2500 in takes 14.385581 hp for 171.610889 bbl/d and 2.2500 in takes 23.587228 hp for 468.819923 bbl/d.", "The speed, since the horsepower only reaches 24.676711395 hp at 12.0 spm.", "The damping ratio, since 0.0500 gives 353.253676 bbl/d for 15.588073 hp.", "Neither one, because the design holds 0.059879964 hp per bbl/d fixed across both sweeps."]'::jsonb, 0, 'A plunger under twice the diameter buys well over twice the oil for well under twice the power, and the damping ratio is a property of the string being described rather than a lever anyone turns.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 13, 'The 2.2500 in plunger on ODUMA-4 returns 468.819923 bbl/d for 23.587228 hp. What comes with it?', '["notPeriodic and converged false, since the heavier fluid load of 7753.352494 lb keeps the string from settling into a repeating stroke.", "structuralOverload, from a reported peak polished rod load of 22756.352510 lb against the structural capacity of the unit.", "rodOverstressed, and a worst section loading of 102.235377 percent.", "Nothing at all, since the row comes back with ok true and a complete set of loads, stresses and rates populated."]'::jsonb, 2, 'That warning is what a bigger plunger actually costs, and the design still returns a complete result carrying every one of those numbers.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 14, 'Walk from the 18.955924637 hp at the polished rod towards the supply. How much of what you pass does the engine model?', '["The gearbox, through the torqueGroup of 0.000000000.", "None of the beam, the gearbox, the belts, the motor or its power factor.", "The motor, through a power check that raises a warning when the prime mover could not deliver the horsepower the card implies.", "The belts and the gearbox, whose losses are what the 337428.720850 in-lb per cycle between the surface and the pump card pays for."]'::jsonb, 1, 'The engine''s own statement of what it does not model names gearbox and belt and motor losses in one breath, and nothing on the warning list is about power.'),
  ('rodpump', 'intermediate', 'module', 'm04-power', 15, 'Is 18.955924637 hp an upper bound on the meter, a lower bound, or neither?', '["Neither, because losses push a meter reading up while counterbalance work pushes it down, and the engine supplies neither correction.", "A lower bound, since every component between the polished rod and the meter adds a loss.", "An upper bound, since the counterweight returns work on the downstroke.", "A lower bound at the defaults and an upper bound once a balance is passed."]'::jsonb, 0, 'Ordering a motor off the figure, or reading a meter and calling the disagreement an engine error, are the same mistake in two dresses: the two numbers are measured at two points.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 1, 'ODUMA-4 runs at a fillage of 0.9 and a pump efficiency of 1. Where did the engine get the fillage?', '["From the pump card, where the length of the fluid load side against the length of the plunger travel gives the fraction of the barrel that filled.", "From the intake pressure of 150 psia against the discharge pressure of 2100 psia, which is the differential the barrel fills against.", "From the march, which reports the fraction of the downstroke the plunger spent in the POUND_DOWN state on the settled cycle.", "From the caller, who typed it."]'::jsonb, 3, 'The engine is given no inflow relation, no fluid level and no gas fraction anywhere, so it has no way to work out how full the barrel is and it believes what it is told.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 2, 'What does the fillage do once it is inside the march?', '["Nothing, since it is applied to the swept volume after the march has finished and the march never sees it.", "It changes the plunger stroke, because the fluid load stays on the plunger while it travels down through the empty part of the barrel.", "It shortens the surface stroke the four-bar delivers, which is how a partly filled barrel reaches the polished rod.", "It scales the fluid load, since a barrel that fills nine tenths of the way puts nine tenths of the column on the plunger."]'::jsonb, 1, 'The march calls that state POUND_DOWN, and the travel it covers is inside the plungerStrokeIn the design reports.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 3, 'The ODUMA-4 plunger stroke reads 95.508351 in at a fillage of 1.0000 and 98.526653 in at 0.9000. Why is the shorter stroke the fuller barrel?', '["The string stays loaded into the downstroke on the partly filled barrel instead of unloading at the top of it, so the plunger carries on travelling.", "The full barrel returns a shorter stroke because the fluid it lifts is heavier, and a heavier column stretches the rods further.", "The partly filled barrel is marched at a lower effective speed, so its overtravel is larger and its plunger stroke longer.", "The two strokes are the same march and the difference is the decimation, which keeps 186 points and lands differently on each run."]'::jsonb, 0, 'It is the opposite of what most people expect, and it is why a design at 0.9000 is a different card rather than the same machine making less oil.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 4, 'Over the whole ODUMA-4 fillage sweep the longest plunger stroke is 100.412132 in at 0.8200 and the shortest is 93.281671 in at 0.5500, against 95.508351 in at a full barrel. What does that rule out?', '["The pound down mechanism, since a stroke that turns cannot be produced by a state that only ever adds travel.", "The sweep itself, because a quantity that is not monotone in its input has not converged and the rows should be rerun at a finer resolution.", "Any single sentence about which way the plunger stroke moves with fillage, since it rises, turns and comes back.", "The use of the marched stroke in the volume, since a rate built on a stroke that turns would not be monotone in fillage either."]'::jsonb, 2, 'A design at 0.5500 has a shorter plunger stroke than a full barrel and one at 0.8200 has a longer one, which is what says this is an accounting question rather than an approximation.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 5, 'ODUMA-4 returns 380.874258458, 351.739329047 and 316.565396142 bbl/d. Which stroke does each stand on?', '["The plunger stroke, the surface stroke, and the surface stroke with the fillage applied, since a rating is always the smallest of the three.", "The surface stroke for all three, with the second and the third scaled by the ratio Sp over S of 0.923505123 and then by the fillage.", "The marched stroke for all three, since every rate in the object is built from the card and the card is one march.", "The surface stroke, the plunger stroke, and the plunger stroke again with the fillage and the pump efficiency applied."]'::jsonb, 3, 'All three arrive in the same unit in the same object with nothing on their faces to say which is a rating and which is an answer.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 6, 'Produced over rated comes back as 0.831154611 on ODUMA-4. What are the two steps down that column?', '["The volumetric efficiency of the pump and then the shrinkage of the produced fluid between the barrel and the tank.", "The stroke the rods gave away, and then the fillage and the pump efficiency.", "The fillage first, applied to the rating, and then the plunger stroke, which is what the fillage left of the travel.", "The slippage past the plunger and the leakage past the travelling valve, which are the two losses the pump efficiency of 1 sets aside."]'::jsonb, 1, 'The rating is built on a surface stroke of 106.687716837 in that the plunger never sees, and the march returns 98.526653100 in instead.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 7, 'A design sheet for ODUMA-4 carries 380.874258458 bbl/d as the deliverability of the well. What is wrong with that?', '["Nothing is wrong with the figure, only with the precision, since a rating quoted to nine figures implies a certainty the design does not have.", "It is the swept rate, and the 351.739329047 bbl/d already carries the plunger stroke.", "It is a multiplication over a stroke the pump never travels, at a fillage nobody checked, in place of 316.565396142 bbl/d.", "It leaves out the pump efficiency, which here is 1, so the sheet would be right where the plunger did not leak."]'::jsonb, 2, 'It is the first number anyone writes down because it is the first one the arithmetic reaches.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 8, 'ODUMA-4 at a fillage of 0.8500 makes 301.389964 bbl/d and at 0.8499 it makes 301.354487 bbl/d. What separates the two designs?', '["0.035477 bbl/d of production, and a warning that one of them raises and the other does not.", "A change in the pump state, since incompleteFillage marks the fillage at which the plunger begins to pound down through an empty barrel.", "Nothing at all, because the threshold sits at 0.85 and both of those rows are above it.", "A step in the plunger stroke, which moves from 99.321361 in to 99.321354 in as the design crosses the line and the pound down travel is added."]'::jsonb, 0, 'The comparison is hard, with no hysteresis and no graduation, so a threshold placed on a continuous quantity puts a step in the report where there is no step in the well.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 9, 'A stack of ODUMA-4 designs comes back and one of them raises no warnings. What has that silence established?', '["That the fillage is at or above 0.85 and the design is not pounding.", "That a comparison came back false, which is not the same as a full barrel.", "That the design passed every check the engine makes, since a warning is raised for each of the eight conditions the engine tests.", "That the fillage, the rod loading and the unit ratings were all inside their limits at the resolution the march was run at."]'::jsonb, 1, 'The row at 0.8500 raises nothing and is pounding just as hard as the row at 0.8499 that speaks, and both of them are pounding.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 10, 'The warned ODUMA-4 design at a fillage of 0.8499 prints a message. What does its percentage say?', '["The barrel fills only 84.9 percent, rounded down from the fillage so that the message can never overstate how full the barrel is.", "The barrel fills only 85.0 percent, which is correct, since the warning is raised on the rounded fillage rather than on the typed one.", "It prints no percentage at all, and names the three remedies instead: slow it down, shorten the stroke or fit a smaller plunger.", "The barrel fills only 85.0 percent, which is the threshold the design has just failed."]'::jsonb, 3, 'The figure is rounded to a whole number of percent, so the text tells a reader the design sits on the limit when it sits below it, and at 0.8480 it says 84.8 percent.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 11, 'Walking the ODUMA-4 fillage down, rodOverstressed appears at 0.7200 and 0.7000 and is gone again at 0.6500, while incompleteFillage stays on throughout. What follows for a reader sorting designs by warning count?', '["Two warnings at 0.7000 against one at 0.6500 does not make 0.7000 the worse design.", "The sweep is unreliable below 0.7000, since a warning that clears as an input is walked further in the same direction is a sign the march has stopped converging.", "rodOverstressed is the warning to sort on, because it is the only one raised against a computed allowable rather than against a typed constant.", "The count is a fair ordering as far as 0.7000, and the rows below it are outside the range the engine will speak about."]'::jsonb, 0, 'Nothing moved between those rows but the fillage, and the fix is free: read the fillage, which the caller typed and can always be printed beside the result.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 12, 'The effective factor on ODUMA-4 at a nominal fillage of 0.9000 is 0.928442245. How is it formed and what is it?', '["It is the fillage times the pump efficiency, and it is the factor the design was asked to apply.", "It is the plunger stroke at 0.9000 over the plunger stroke at a full barrel, and it is the travel the pound down state added.", "It is the produced rate over the produced rate at a full barrel, and it is the factor the design really applied.", "It is the produced rate over the rated displacement, and it is the whole chain from the barrel to the tank on this design."]'::jsonb, 2, 'It comes out 3.160249 percent above the number typed in, because a fillage multiplier is charged against a swept volume the same fillage already changed.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 13, 'The effective factor runs 5.134400 percent above the nominal fillage at 0.8200 and 2.331398 percent below it at 0.5500, on one design with one input moved. Why does that settle the argument?', '["Because a sweep that changes sign has crossed a root, and the fillage at which it crosses is the one the design should be run at.", "A convention can be optimistic or conservative and still be a convention, but one that changes sign has no direction to defend and no correction to apply.", "Because the two figures bracket zero, so the error cancels over the range and the nominal fillage is the right factor on average.", "Because the larger of the two is the one that matters, and 5.134400 percent is inside the 2 percent the published gates hold the routes to."]'::jsonb, 1, 'Across the twenty contiguous rows the effective factor sits above the nominal on sixteen and below it on three, so one case tells you nothing about the next.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 14, 'An engineer multiplies the ODUMA-4 rating of 380.874258458 bbl/d by the fillage of 0.9000 by hand. What is that answer?', '["Neither the produced rate the engine returned nor the well, since the rating stands on the surface stroke and the effective factor was 0.928442245.", "The produced rate, since that multiplication is exactly what runRodPumpDesign does to reach 316.565396142 bbl/d.", "The swept displacement of 351.739329047 bbl/d, which is the rating with the fillage taken out of it.", "A conservative estimate, since the hand figure always falls below the engine figure once the pound down travel is counted."]'::jsonb, 0, 'The engine builds its swept rate from the marched plunger stroke of 98.526653100 in and then applies the fillage to that, so no hand arithmetic on the rating reproduces it.'),
  ('rodpump', 'intermediate', 'module', 'm05-what-the-well-makes', 15, 'One chain on an ODUMA-4 design sheet carries the production. What is it, and where does it stop?', '["The rated displacement times the produced over rated ratio of 0.831154611, and it stops at the tank.", "The card area of 750654.615621 in-lb per cycle over the speed, and it stops at the polished rod where the horsepower is measured.", "The marched plunger stroke times the plunger area times the fillage and the pump efficiency, and it stops at the barrel.", "The load range against the buoyed weight, and it stops where the engine''s inflow relation takes over below the pump."]'::jsonb, 2, 'Everything else in the return object is a load, a stress, a power or a ratio, and the engine cannot say whether the well can supply what the pump would lift because it was never asked what the well has.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'One sentence carries the whole Professional tier. Which?', '["Every number a rod pump design reports is read off a card, and reading it means naming the stroke it stands on, the speed it was marched at and the two numbers the caller typed.", "Every number a rod pump design reports follows from the string and the linkage, so a design is settled once the geometry is fixed and the march only confirms it.", "Every number a rod pump design reports is a measurement of the well, taken through a rod string that the march removes from the reading.", "Every number a rod pump design reports is bounded by the closed forms, so a marched answer that leaves those bounds is the one to distrust."]'::jsonb, 0, 'The two typed numbers are the fillage and the pump efficiency, and on the teaching design they take a swept 351.739329047 bbl/d down to a produced 316.565396142 bbl/d.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Of the five module claims, which one can be checked without running a march at all?', '["The load range, because peak minus minimum is arithmetic on two numbers the design already reports rather than a march of its own.", "The horsepower, because the card area times the speed over 396000 is a multiplication and a division.", "The spring rule, since 64.000000 in less 18.720185299 in is 45.279814701 in and nothing in it depends on speed.", "The produced rate, because it is the rated 380.874258458 bbl/d scaled by the fillage the caller typed."]'::jsonb, 2, 'The other four all stand on a card: the loads, the range, the area and the plunger stroke that feeds the rates are all read off a marched loop.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'The order of work puts the string and the pump before anything is marched. What belongs in that first step?', '["Weight, buoyed weight, plunger stroke and fluid load, which are the four quantities the design reports before the card is drawn.", "Weight, buoyed weight, spring rate, elastic constant, linkage stroke, plunger area and fluid load, none of which depends on speed.", "The string, the linkage and the damping ratio, since damping is a property of the steel and the fluid rather than of the running speed.", "The string and the pump at the design speed, because the plunger area and the fluid load both move with the speed the unit will run at."]'::jsonb, 1, 'All of it is closed form, so a build that is wrong there is wrong in every marched number that follows and the march will not say so.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Why does the order of work put the string''s note before the choice of a speed?', '["The note sets the time step of the march, so a speed chosen first would be marched at the wrong resolution.", "The note is the speed at which the plunger stroke is longest, so it is the speed a design is chosen to run near.", "The note decides the damping ratio, since a string driven near its own frequency needs more damping to settle.", "The engine refuses any design at or above the fundamental, so a speed chosen first can be refused rather than adjusted."]'::jsonb, 3, 'The refusal names the number in its message, as ODUMA-4 does with a fundamental of 59.134268421585 spm on a design running at 10 spm.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Walking the damping ratio across nine rows of one design moves the peak load 2223.684206 lb, the plunger stroke 13.541308 in and the horsepower from 15.588073 to 24.404568 hp. What does the order of work say to do with it?', '["Fit it, by walking the ratio until the loads match a measured card.", "State it, and treat it as an input rather than a default, since nobody measures it.", "Leave it at the shipped default, since the engine''s own message puts the field range between about 0.05 and 0.15 of critical and the default sits inside it.", "Report the spread instead of the value, since a quantity that moves the peak by that much cannot be reduced to one number on a sheet."]'::jsonb, 1, 'It is the input with no measurement behind it and the largest unearned authority, and the field range in the engine''s message is a range and not a value.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The march returns 49.670227367 in on the published taper at 9 spm and the spring rule returns 45.279814701 in. What does the order of work say to report?', '["The spring rule, since it is closed form and the march is a reading off a curve.", "Both, with the design sized on whichever is the more conservative.", "The marched number, with the difference quoted beside it and named as overtravel.", "The marched number alone, since the spring rule is the static limit of the same quantity and adding it to a sheet invites the reader to average the two."]'::jsonb, 2, 'The gap is 9.696181 percent at that speed, and it is inertial overtravel rather than a disagreement to be resolved.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Step five of the order of work reads the two loads together rather than one at a time. What does that add?', '["A peak of 16490.601223 lb and a minimum of 5823.210940 lb say more standing 7816.843261277 lb above and 2850.547021552 lb below a buoyed weight of 8673.757961783 lb.", "A load range, which is the only quantity in the design that carries both ends of the card and is therefore what the steel feels.", "A check on the march, since a peak and a minimum that straddle the buoyed weight are what a converged run produces.", "The two RP 11L groups F1 over Skr and F2 over Skr, which are the peak and the minimum written on the load scale of the string."]'::jsonb, 0, 'The distance from the static datum is what the word dynamic means, and neither load carries it alone.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A design sheet states a produced rate on its own. Why is that not reportable?', '["The rate is built from the marched plunger stroke, so it needs the speed and the damping ratio quoted with it before it can be read.", "A produced rate has to be stated against the rated displacement, since the ratio of the two is the only figure that carries the rod string.", "The engine returns three rates, so any one of them quoted alone will be read as the rating, which is the largest of the three.", "It stands on a fillage and a pump efficiency the caller typed, and neither is beside it."]'::jsonb, 3, 'The order of work takes the plunger stroke into a rate and then puts both typed numbers beside the answer, because the rate is only as good as they are.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The slow speed identity is run first among the checks. What does it check?', '["That a near static march collapses onto the spring rule, 45.286791250 in against 45.279814701 in, with the two loads landing on the buoyed weight plus the fluid load and on the buoyed weight alone.", "That the march has converged, since a run that settles at a slow speed will settle at a working speed on the same string.", "That the damping ratio is inside the field range, since a wrong ratio shows up as a slow speed answer that misses the spring rule.", "That the decimation is fine enough, since a slow run marches more steps and keeps the same number of card points."]'::jsonb, 0, 'The gap is 0.015408 percent, and a build that misses that identity is wrong before any dynamic number is read.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Why does the order of work read the converged flag and the warning list before any number is read?', '["Because a warning empties the fields it applies to, so a number read before the list may not be there at all.", "Because the warning list is ordered by severity, so the first code on it names the number that should be read first.", "Rows come back with notPeriodic inside an ordinary damping range, and they still report a full set of numbers.", "Because a design that raises no warning has passed every check the engine makes and needs no further reading."]'::jsonb, 2, 'Three rows of the nine row damping sweep on the teaching design come back with converged false inside the band the engine''s own message calls the field range.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A reviewer sorts two teaching designs by their warning lists: 301.389964 bbl/d silent above 301.354487 bbl/d warned. What has the sort done?', '["Ordered them correctly, since the warned design is pounding and the silent one is not.", "Put 0.035477 bbl/d of production in an order decided by a hard threshold rather than by either well.", "Ordered them by fillage, which is the input the threshold reads and the only input separating the two designs.", "Ordered them by production, since the silent design makes more and the two orderings happen to agree on this pair."]'::jsonb, 1, 'Reading silence from the warning list as a full barrel is one of the failures the tier names, and the fix is to print the fillage beside the result.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'An engineer multiplies a rating by a nominal fillage of 0.9000 and expects the engine''s produced rate. What does the tier say goes wrong?', '["The rating is on the surface stroke and the produced rate is on the plunger stroke, so the two differ by the ratio Sp over S of 0.923505123.", "The pump efficiency is missing from the hand arithmetic, and on the teaching design it is the second of the two typed numbers.", "The hand figure lands on the swept rate of 351.739329047 bbl/d instead, which is the rating with the rod string taken out of it.", "The factor the design actually applied was 0.928442245, not the number typed."]'::jsonb, 3, 'The fillage is charged against a swept volume the same fillage already moved, so the effective factor is not the nominal one and no hand multiplication reproduces the engine.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'What does the Professional tier explicitly leave unsettled?', '["Which of a design''s numbers are measurements and which are artefacts of how the card was sampled.", "Whether the marched plunger stroke or the spring rule is the stroke a volume should be built on.", "Whether the peak polished rod load or the load range is the number a beam and a structure should be sized against.", "Whether the horsepower at the polished rod is an upper or a lower bound on what a meter at the lease would read."]'::jsonb, 0, 'The card is still the design and everything in this tier stays in force, but the sampling question belongs to the tier that follows.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'On the teaching design the tension envelope implies a peak of 19851.465785541 lb while the reported field says 19545.877783339 lb. What is the 305.588002202 lb between them?', '["The dynamic part of the peak, which the envelope carries and the reported card leaves on the static datum.", "The convergence error of the march, which is why raising the node count moves the loads by hundreds of pounds.", "Two samplings of one march disagreeing inside one return object.", "The counterbalance moment written as a load at the polished rod, which the envelope includes and the card does not."]'::jsonb, 2, 'The card kept 186 points out of 6110 marched steps, and off that subsample the reported minimum is 24.755505 percent above the marched one while the plunger stroke does not move by a single figure.'),
  ('rodpump', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'A speed sweep dips 1.470226 percentage points on the worst section loading, and moving the node count alone moves the same number 4.283675 percentage points at the speed before the dip and 6.553883 after it. What is the dip?', '["A real optimum that is hard to resolve, so it should be quoted with the node spread beside it as an uncertainty.", "Smaller than the solver''s own noise, so it is not an optimum and not a result.", "A resonance, since the loading falls where the pumping speed passes a fraction of the string''s own fundamental.", "An artefact of the decimation, which lands differently at every speed and is removed by raising the card sample count."]'::jsonb, 1, 'The node count changes nothing about the well, so a movement it produces bounds what any sweep on this solver can claim to have found.'),
  ('rodpump', 'intermediate', 'final', null, 1, 'A design review calls the loop predictCard returned the well''s card. What is the objection?', '["It is a pump card, and only a surface card can be compared with what a dynamometer records.", "It was computed rather than recorded, out of a fluid load, a surface motion and a damping ratio somebody typed.", "It is the decimated card, and a comparison with a measurement would have to be made against the tension envelope instead.", "It is one settled cycle, and a measurement is an average over many strokes, so the two are different quantities before anything else is said."]'::jsonb, 1, 'The package holds a separate solver, diagnoseCard, for cards that were measured, and the two share no code path.'),
  ('rodpump', 'intermediate', 'final', null, 2, 'One ODUMA-4 figure reads the same whether the card keeps 186 points or every marched step. Which one, and what does that protect?', '["The peak polished rod load, since a maximum is the extreme a coarse sample is most likely to land on, which makes the structural check the safe half of the design.", "The plunger stroke, taken peak to trough at the pump node over every step, so the swept and produced rates never touch the subsample.", "The card area, since a shoelace integral around a closed loop is insensitive to how finely the loop was sampled, and the horsepower inherits that.", "The minimum polished rod load, since it is pinned to the buoyed rod weight of 9466.342675159 lb rather than read off the returned card at all."]'::jsonb, 1, 'The stroke reads 98.526653100 in either way, while the reported minimum of 2625.472706 lb is 1.247555 times the marched 2104.494479 lb.'),
  ('rodpump', 'intermediate', 'final', null, 3, 'ODUMA-4 prices its top section from an envelope sample taken 20.000000000 ft below the polished rod. What does that cost, and is it the tier''s finding?', '["It leaves 51.421146497 lb of buoyed rod out of the section load, which is 0.259029 percent, and it is a discretisation choice rather than the finding.", "It leaves 305.588002202 lb out, which is the whole disagreement between the two peak loads the one return object carries, so it is exactly the finding.", "It costs nothing at all, since the envelope is accumulated over every one of the 6110 marched steps and a maximum accumulated that way is the same at any depth.", "It raises the section percentage rather than lowering it, since a lighter load against a fixed Goodman allowable of 30420.168218 psi always reads as the larger fraction."]'::jsonb, 0, 'The section reports 82.873308396 percent of its allowable, and half a node of missing rod is 0.259029 percent against the 1.563440 percent the two peak routes differ by.'),
  ('rodpump', 'intermediate', 'final', null, 4, 'A caller asks for a card at a damping ratio of 0. What does the engine do, and what does the message say?', '["It returns a card with notPeriodic attached, since an undamped string is what that flag exists for.", "It marches to the maxCycles limit of 20 and returns the last cycle with converged false.", "It refuses, saying the string never settles into a repeating stroke and that field strings sit between about 0.05 and 0.15 of critical.", "It substitutes the shipped default, because damping enters as a coefficient rather than as a friction model."]'::jsonb, 2, 'It is a refusal rather than a warning, so nothing is returned, and the message names the range the caller was probably reaching for.'),
  ('rodpump', 'intermediate', 'final', null, 5, 'At a damping ratio of 0.0500 ODUMA-4 comes back with a plunger stroke of 109.945379 in, longer than the 106.687716837 in the linkage gives the polished rod. Is that reportable?', '["No, because a plunger cannot travel further than the polished rod above it, so the row is arithmetic that has gone wrong inside the decimation.", "Yes, because inertial overtravel routinely adds a tenth of the stroke and that row is simply the lightly damped end of the same effect.", "No, because the same row came back with converged false and notPeriodic, so the loop it was read off never repeated.", "Yes, because the engine refuses any design it cannot stand behind, so a design it returned at all has passed the checks that matter."]'::jsonb, 2, 'Overtravel really can carry the plunger past the surface stroke, so the objection has to be the flag and not the physics: that row reports 353.253676 bbl/d looking exactly as confident as a settled one.'),
  ('rodpump', 'intermediate', 'final', null, 6, 'At 0.5 spm the published taper marches to within 0.015408 percent of the spring rule, yet its peak of 13756.379902 lb sits above the static sum of 13673.757962 lb. What does that pair say?', '["The spring rule is the wrong reference for any load at all, since it was only ever written for the stroke, so comparing a marched peak against a static sum of rod weight and fluid load settles nothing at any speed.", "The march has not converged at half a stroke a minute, which is why one of the two quantities lands on its closed form and the other does not.", "The peak is read off the decimated card while the stroke is not, so the extra pounds are a coarse sample landing high on a slow run.", "The stroke has reached its static limit before the loads have, because a travel is a difference of two turning points and a load is an extreme that keeps the last of the motion."]'::jsonb, 3, 'The minimum on the same row is 8586.448887 lb against a buoyed weight of 8673.757961783 lb, so both loads are near their static datums and neither is exactly on one.'),
  ('rodpump', 'intermediate', 'final', null, 7, 'On ODUMA-4 the surface stroke is 106.687716837 in, the fluid load 4690.299657039 lb and Er 3.312268708e-3 in/lb. What does the spring rule return, and does the speed enter it?', '["98.526653100 in, once the pumping speed of 10 spm has been applied to the static subtraction.", "15.535532787 in, which is the stretch the fluid load removes before the plunger moves.", "91.152184050 in, and the speed does not enter it at all.", "91.152184050 in at the design speed, rising toward the surface stroke as the unit is slowed toward the static limit."]'::jsonb, 2, 'S less Fo Er is 106.687716837 in less 15.535532787 in, and there is no term in it for time, mass or speed.'),
  ('rodpump', 'intermediate', 'final', null, 8, 'ODUMA-4 overtravels 8.090282 percent at its design speed. Where in the returned design does that 8.090282 percent end up?', '["In the swept and the produced rates, because displacementBpd is fed the marched stroke and not the closed form one.", "In the peak and the minimum loads, because a longer plunger travel is a longer load transfer and the two extremes move with it.", "In the rated displacement of 380.874258458 bbl/d, because a rating is what the design says the pump can sweep at its own travel.", "Nowhere, because overtravel is reported as a comparison between two routes and the design is built on the closed form throughout."]'::jsonb, 0, 'The swept 351.739329047 bbl/d stands on 98.526653100 in and not on the rule''s 91.152184050 in, so the inertia is inside every barrel figure on the sheet.'),
  ('rodpump', 'intermediate', 'final', null, 9, 'Overtravel at 9 spm on the published taper runs 3.020373 percent under 1000.0 lb of fluid load, 1.439066 under 2000.0 and 3.521722 under 3000.0. A designer proposes sizing the plunger to sit in that trough. What is wrong?', '["Nothing is wrong with the reasoning, since the fluid load is a differential times an area and the plunger bore is the only term in that product a designer is free to move at all.", "The overtravel should be maximised instead, since it is travel the barrel is handed for nothing above what the closed form promised.", "The ladder is not monotone, so a trough three rows wide is not a minimum, and the plunger that sets the fluid load sets the rate and the section loading with it.", "The fluid load cannot be chosen at all, since it follows from the discharge and intake pressures and the bore only moves the rated displacement."]'::jsonb, 2, 'Overtravel grows in the large and not in the small, and the 1.2500 in and 2.2500 in plungers that would move the load that far make 171.610889 and 468.819923 bbl/d.'),
  ('rodpump', 'intermediate', 'final', null, 10, 'A study ranks ODUMA-4 speeds by overtravel and puts 5.0 spm at 1.358400 percent below 6.0 spm at 1.358619 percent. What is wrong with the ranking?', '["The ranking is upside down, since overtravel rises with speed and the faster of any two rows has to be the larger of the two.", "Two ten thousandths of a percentage point separate the rows, on a quantity whose two independent routes disagree by 0.637731 percent.", "Nothing is wrong, since both rows came back converged and carrying no warnings, and a converged row is a row that may be quoted.", "The ranking should have been made on the closed form instead, which is the one route to the stroke that no second scheme can disagree with."]'::jsonb, 1, 'That gap sits far inside the difference between the engine and the oracle on the very same quantity, so the ordering carries no information at all.'),
  ('rodpump', 'intermediate', 'final', null, 11, 'displacementBpd is fed one of the two plunger strokes. Which, and on what grounds?', '["The spring rule one, because a volume should stand on a closed form rather than on a reading off a sampled march.", "The surface stroke, because the rating the design reports is what the linkage delivers to the polished rod.", "The marched one, because it is the travel the plunger makes inside the barrel and therefore the travel that sweeps volume.", "Whichever is smaller, since a design reports the conservative of two defensible routes to the same quantity."]'::jsonb, 2, 'On ODUMA-4 that is 98.526653100 in against a surface stroke of 106.687716837 in, and Sp over S comes back as 0.923505123.'),
  ('rodpump', 'intermediate', 'final', null, 12, 'The ODUMA-4 peak is read at cycle fraction 0.151227 and the minimum at 0.718331, which are not half a cycle apart. What does the design do about that?', '["It moves the minimum onto the opposite half of the cycle, which is what the reported load range of 16920.405077660 lb is defined as.", "It raises notPeriodic, since two extremes that are not half a cycle apart are the signature of a march that has not settled.", "It reads the minimum off the pump card instead, since only that card carries the two valve transfers the load transfer can be located by.", "Nothing, because a card is a loop and its two extremes fall wherever the returning wave puts them."]'::jsonb, 3, 'A settled loop is all the engine claims, and 19545.877783339 lb and 2625.472705679 lb are simply the highest and the lowest of the 186 points it kept.'),
  ('rodpump', 'intermediate', 'final', null, 13, 'The engine returns peaks of 15230.601238973 lb and 16490.601223060 lb where the oracle committed 15231.366293700 lb and 16545.574080121 lb. What does that pair establish?', '["The engine runs low on peak load and the bias grows with speed, so a working peak should be raised before use.", "The two routes fall outside the published gates at 9 spm, so no peak claim can be made at that speed.", "The oracle is the finer scheme, since it marches a staggered grid with RK4 and returns the larger peak on both runs.", "The peak is the best behaved of the three headline numbers, at -0.005023 percent on one run and -0.332251 percent on the other."]'::jsonb, 3, 'Two schemes with different unknowns, different grids and different integrators, five thousandths of a percent apart at one speed.'),
  ('rodpump', 'intermediate', 'final', null, 14, 'Why is the minimum polished rod load measured against the buoyed rod weight alone?', '["The travelling valve opens on the downstroke and the fluid load transfers to the tubing, leaving the rods.", "Because a minimum is only meaningful as a margin above the slack rod condition, which is zero load.", "Because the fluid column pushes up on the plunger through the downstroke, so its weight is subtracted from the rods.", "Because both extremes are read off one card, and a card can only carry one datum for the cycle it describes."]'::jsonb, 0, 'At 0.5 spm the published taper bottoms at 8586.448887 lb against a buoyed weight of 8673.757961783 lb, and at 9 spm it sits 2850.547021552 lb below it.'),
  ('rodpump', 'intermediate', 'final', null, 15, 'The design delivers two verdicts off one march, whether the unit is overloaded and whether the rods go into compression. Which one rests on the worse agreed number?', '["The compression verdict, since the minimum is what the published gates give 3 percent and what the two routes sit 1.057795 percent apart on at 5 spm.", "The overload verdict, since the peak is the larger of the two numbers and a larger number carries a larger absolute disagreement between any two marching schemes.", "Neither, since both verdicts are read off one card and a single card cannot be better known at one end of itself than at the other.", "The overload verdict, since it is taken against a unit rating, and a catalogue rating is a figure the engine has no independent route to at all."]'::jsonb, 0, 'On the peak the same two runs sit 0.005023 and 0.332251 percent apart, and the published gates name only the plunger stroke at 2 percent and the minimum at 3.'),
  ('rodpump', 'intermediate', 'final', null, 16, 'Walking the ODUMA-4 fillage down from 0.9000 to 0.7200 makes less oil and raises rodOverstressed. What has emptying the barrel done to the steel?', '["Nothing, since the warning is raised on the typed fillage and the worst section loading of 82.873308396 percent is fixed by the string and the fluid load.", "Loaded it harder, because the fluid load stays on the rods through the pound down travel instead of transferring at the top of the stroke.", "Unloaded it, since a partly filled barrel lifts a shorter column of fluid and the peak polished rod load falls with the weight standing above the plunger.", "Loaded it harder, because the shorter plunger stroke at a low fillage forces more strokes a minute to hold the rate and fatigue follows the cycle count."]'::jsonb, 1, 'The warning list at that fillage carries rodOverstressed and incompleteFillage together, so the design making the least oil in that stretch of the sweep is the one working its rods hardest.'),
  ('rodpump', 'intermediate', 'final', null, 17, 'Two ODUMA-4 sheets are ranked on peak load, 19545.877783339 lb at the shipped damping against 19231.260898 lb at a damping ratio of 0.1000. Which is the lighter loaded design?', '["The 0.1000 row, since it is the smaller peak and both rows come off one string, one linkage and one fluid load with a single input moved.", "The shipped row, since a lower damping ratio always understates the loads and the 0.1000 row has to be corrected upward before any comparison.", "Neither can be said, because the lower of the two rows came back with converged false and notPeriodic.", "The 0.1000 row, since a lighter damped string absorbs less of the polished rod''s work and its load range of 16391.417339 lb is the narrower of the two."]'::jsonb, 2, 'A warning means an answer was produced anyway, so the unsettled row reports a full peak, a full stroke and 319.059539 bbl/d looking exactly like the settled one.'),
  ('rodpump', 'intermediate', 'final', null, 18, 'A reviewer divides the ODUMA-4 pump card area of 413225.894771 in-lb per cycle by its 316.565396142 bbl/d and calls the answer the energy in a barrel. Name the error that is not the units.', '["The loop is drawn against the plunger''s own travel rather than the polished rod''s, so its area was measured at the wrong end of the string to be anybody''s work in the first place.", "Part of that loop is the plunger travelling down through an empty barrel at a fillage of 0.9 with the fluid load still on it, and none of that work lifted anything.", "The produced rate already carries the pump efficiency of 1, so a division by it counts the same efficiency into the answer twice over.", "The loop is the smaller of the two by 337428.720850 in-lb per cycle, and it is the surface loop that a lease actually pays for."]'::jsonb, 1, 'Away from the transfers the pump load is 4690.299657039 lb while the plunger is lifting or pounding down, and the engine never separates those two states.'),
  ('rodpump', 'intermediate', 'final', null, 19, 'What is the card area, as a piece of arithmetic?', '["A trapezoidal integral of load against time over the settled cycle, converted to work by the speed.", "The mean load over the cycle times the plunger stroke of 98.526653100 in.", "The peak load of 19545.877783339 lb times the full 106.687716837 in of polished rod travel.", "A shoelace integral around a closed loop of load against position, which is why the march runs until the cycle repeats."]'::jsonb, 3, 'ODUMA-4 takes four cycles to settle, and a loop that has not closed does not enclose an area worth integrating.'),
  ('rodpump', 'intermediate', 'final', null, 20, 'The ODUMA-4 card is summarised twice inside one return object, as a load range of 16920.405077660 lb and as an area of 750654.615621 in-lb per cycle. What does each summary give up?', '["The range gives up the damping and the area gives up the speed, which is why only the area has to be multiplied by 10 spm before it becomes power.", "The range gives up the pump end and the area gives up the surface end, so the two of them together are the string read from both of its ends.", "Neither gives anything up, since the range is the height of the loop and the area is its integral, and a height with an integral fixes a closed curve.", "The range keeps two points and gives up the shape, and the area keeps the shape and gives up where in the cycle any load occurred."]'::jsonb, 3, 'One of them prices the swing the steel feels and the other prices the work the polished rod did, and the order the loads arrived in is in neither.'),
  ('rodpump', 'intermediate', 'final', null, 21, 'ODUMA-4 goes from 8.791354106 hp at 6.0 spm to 24.676711395 hp at 12.0 spm. Why is that more than double?', '["The card area grew from 580229.370988 to 814331.476024 in-lb per cycle underneath the multiplication.", "The extra speed raised the fluid load, and the fluid load is the largest term in the card.", "The horsepower is quadratic in speed by construction, since the speed appears in the constant 396000 as well.", "The slower row had not converged, so its area was low and the ratio between the two rows overstates the climb."]'::jsonb, 0, 'The speed is in the answer twice, so a designer who prorated the low figure would size surface equipment for a machine that does not exist.'),
  ('rodpump', 'intermediate', 'final', null, 22, 'Which ODUMA-4 headline number could a designer working only from the fluid load and the spring rule not produce at any speed?', '["The plunger stroke, because the rule''s 91.152184050 in is a different quantity from the travel the barrel sees and cannot be corrected into it.", "The rated displacement of 380.874258458 bbl/d, because a rating stands on a marched travel.", "The card area of 750654.615621 in-lb per cycle, because a static rule hands over a stroke and a load but never a loop.", "The minimum polished rod load, because a static rule reaches the buoyed weight of 9466.342675159 lb and can never reach a departure from it."]'::jsonb, 2, 'The 18.955924637 hp follows from the area and the speed, so the whole of power in this course is downstream of owning a loop that closed.'),
  ('rodpump', 'intermediate', 'final', null, 23, 'An engineer asked to improve ODUMA-4''s 0.059879964 hp per bbl/d proposes retyping the fillage from 0.9000 to 1.0000. What has the proposal changed?', '["The design on paper only, since fillage is an assertion about the well and the engine holds no inflow relation to check it against.", "The machine, since the fillage enters the march through the pound down state and the plunger stroke moves from 98.526653 in to 95.508351 in with it.", "The power, since a full barrel keeps the full fluid load on the plunger through the whole upstroke and the card area grows with it.", "Nothing at all, since the fillage is applied to the swept rate after the march and a ratio of power to rate divides it straight back out again."]'::jsonb, 0, 'The produced rate moves from 316.565396 bbl/d to 340.964016 bbl/d on that retype, and nothing at the lease has moved at all.'),
  ('rodpump', 'intermediate', 'final', null, 24, 'Retyping only the ODUMA-4 damping ratio takes production from 353.253676 to 309.745554 bbl/d. Which of the three rates the design reports does not move with it, and why?', '["The swept rate, because it is the volume the barrel sweeps and only the fillage and the pump efficiency stand between it and the produced rate.", "None of the three, because all three are formed out of one march and the march is where a damping ratio is applied in the first place.", "The rating of 380.874258458 bbl/d, because it is built on the linkage stroke and the damping never reaches the four-bar.", "The produced rate, because the fillage of 0.9 is applied to it last of all."]'::jsonb, 2, 'The swept and the produced rates both stand on the marched plunger stroke, which moves 13.541308 in across that sweep, while the rating stands on 106.687716837 in.'),
  ('rodpump', 'intermediate', 'final', null, 25, 'Across the fillage cliff the ODUMA-4 plunger stroke moves from 99.321361 in to 99.321354 in. What is the warning responding to?', '["The step in the plunger stroke, which is what marks the fillage at which the plunger has begun to pound down through an empty part of the barrel.", "The typed fillage and nothing else, since incompleteFillage is a comparison against 0.85 made before any card is read.", "The produced rate crossing its own threshold, which is why the two designs report 301.389964 and 301.354487 bbl/d on either side of the line.", "The load transfer sharpening, which is real at that fillage and is what leaves a coarse card least able to find the minimum on the downstroke."]'::jsonb, 1, 'Seven millionths of an inch of travel and 0.035477 bbl/d separate the two designs, and one of them prints a warning that the other does not.'),
  ('rodpump', 'intermediate', 'final', null, 26, 'At a fillage of 0.8499 the warning message prints a percentage. Which, and what is wrong with it?', '["It says 84.9 percent, rounded down so that the message can never overstate how full the barrel is.", "It prints no percentage and names the three remedies instead, which is why the fillage has to be printed beside it.", "It says the barrel fills only 85.0 percent, which is the threshold the design has just failed.", "It says 85.0 percent, which is correct, since the warning is raised on the rounded fillage rather than on the typed one."]'::jsonb, 2, 'The figure is rounded to a whole number, so the text says the design sits on the limit when it sits below it, while at 0.8480 it says 84.8 percent.'),
  ('rodpump', 'intermediate', 'final', null, 27, 'The ODUMA-4 effective factor is 0.928442245 where the nominal fillage is 0.9000. Which half of that gap is defensible?', '["Neither half, since a factor that lands above its nominal on most of a sweep is an error of about 3 percent and belongs in a correction.", "Both halves, since the plunger travel and the fillage multiplier are separate physical effects and applying each of them once is what the arithmetic does.", "The multiplier, since a fillage is the fraction of a barrel that filled and multiplying a swept volume by it is the definition of a produced volume.", "The travel, since the string stays loaded into the downstroke and the plunger really does go further, and not the multiplier charged against a volume the same fillage had already moved."]'::jsonb, 3, 'The error against nominal is 3.160249 percent on that row, and the argument is settled by the sign flipping across the sweep rather than by the size of any one row.'),
  ('rodpump', 'intermediate', 'final', null, 28, 'A sheet lists three ODUMA-4 plunger strokes, 91.152184050, 95.508351 and 100.412132 in. What separates them?', '["The first has no term for speed or fillage, the second is the march at a full barrel and the third is the march at a fillage of 0.8200.", "They are one march at three node counts, which is the spread the plunger travel shows when the grid alone is moved and the well is not.", "They are the spring rule, the marched travel and the surface stroke, which is the order in which a design computes the three of them.", "They are three speeds off the overtravel ladder, and the longest belongs to the fastest because overtravel grows with the speed."]'::jsonb, 0, 'The closed form has no term for either input, and the marched stroke is not monotone in fillage: 100.412132 in at 0.8200 beats 95.508351 in at a full barrel.'),
  ('rodpump', 'intermediate', 'final', null, 29, 'A heavier fluid takes the ODUMA-4 peak from 19750.187337 lb to 19341.568229 lb while rodStretchIn keeps returning 3.312268708 in per 1000 lb. Why is nothing inconsistent there?', '["The stretch is quoted per 1000 lb, which hides a change that would show at once if the fluid load itself were quoted instead.", "The stretch is a static quantity and the peak is a marched one, so the two are computed at different points in the run and cannot be compared.", "The fluid sets the buoyancy factor and so the weight the polished rod carries, while the elastic constant belongs to the steel and the geometry.", "The buoyancy factor is inside the stretch as well, but its move from 0.904458599 to 0.866242038 is too small to show at the figures printed."]'::jsonb, 2, 'The spring rule''s 91.152184050 in does not move down that sweep either, and the plunger stroke stays at 98.526653 in on every one of its rows.'),
  ('rodpump', 'intermediate', 'final', null, 30, 'Why is the slow speed identity run first among the checks?', '["A near static march has to collapse onto the spring rule, and a build that misses it is wrong before any dynamic number is read.", "It is the only check that does not need the march to have converged, so it can be run on a failed design.", "It is the check the published gates are written against, so a design that passes it is inside the 2 percent the gates hold on plunger stroke.", "It is where the two solvers are furthest apart, so passing it bounds the disagreement everywhere else."]'::jsonb, 0, 'The published taper marches 45.286791250 in against a rule of 45.279814701 in at 0.5 spm, which is 0.015408 percent, with the loads landing on their static datums.'),
  ('rodpump', 'intermediate', 'final', null, 31, 'What does the Professional tier state that it has not settled?', '["Whether the marched stroke or the spring rule is the stroke a volume should be built on.", "Which of a design''s numbers are measurements and which are artefacts of how the card was sampled.", "Whether a peak polished rod load or a load range is the right number to size a beam and a structure against.", "Whether the polished rod horsepower is an upper or a lower bound on what a lease meter would read."]'::jsonb, 1, 'The card is still the design and everything in the tier stays in force, but the sampling question belongs to the tier that follows.'),
  ('rodpump', 'intermediate', 'final', null, 32, 'Three numbers on an ODUMA-4 sheet were typed by whoever ran it and one was computed from them. Which was computed?', '["The fillage of 0.9, which the march reports back as the fraction of the downstroke the plunger spends pounding through an empty barrel.", "The damping ratio of 0.12, which the engine fits from the number of cycles the march needed before it settled, four on this design.", "The pump efficiency of 1, which the design forms as the produced rate over the swept rate once the fillage has been taken off.", "The plunger stroke of 98.526653100 in, the peak to trough of the pump node over one settled cycle."]'::jsonb, 3, 'Fillage, damping and pump efficiency all arrive as assumptions, and the produced 316.565396142 bbl/d stands on the three of them at once.'),
  ('rodpump', 'intermediate', 'final', null, 33, 'Taking the ODUMA-4 plunger from 1.2500 in to 2.2500 in raises the rate from 171.610889 to 468.819923 bbl/d and shortens the plunger stroke from 104.686626 in to 88.268838 in. Why does the bigger bore shorten the travel?', '["It raises the volume swept per stroke, and a barrel that takes longer to fill holds the plunger still at the bottom for part of every cycle.", "It takes the fluid load from 2393.010029 lb to 7753.352494 lb, and the static stretch that load causes comes straight off the surface stroke.", "It lowers the natural frequency of the string, so the design sits nearer the fundamental and the march settles onto a shorter travel.", "It takes the peak to 22756.352510 lb, and the engine shortens the travel it reports once rodOverstressed has been raised against the design."]'::jsonb, 1, 'The rule is the surface stroke less Fo Er, so a plunger that more than trebles the fluid load takes the travel down with it before any inertia is added back.'),
  ('rodpump', 'intermediate', 'final', null, 34, 'The Goodman check and the structural rating check on one ODUMA-4 design read two different numbers out of one call. Which is which?', '["Both read the decimated card, since the section loads are interpolated from the surface card down the string.", "Both read the tension envelope, since the reported peak is the shallowest envelope sample taken at 20.000000 ft.", "The Goodman check reads the tension envelope over every marched step, and the structural check reads the peak off the decimated card.", "The Goodman check reads the card and the structural check reads the envelope, which is why the section stresses are the finer of the two."]'::jsonb, 2, 'One design, one march, two samplings, and the reported peak of 19545.877783339 lb comes off the 3.044190 percent of the steps the card kept.'),
  ('rodpump', 'intermediate', 'final', null, 35, 'Walking the ODUMA-4 damping ratio from 0.0500 to 0.2000 raises the horsepower from 15.588073 to 24.404568 hp and moves the peak load 2223.684206 lb. What else does that sweep show?', '["Every row inside the field range converges, and only the rows outside it raise notPeriodic.", "Three of its rows come back with notPeriodic and converged false, inside the band the engine''s own message calls the field range.", "The produced rate rises with the horsepower, since more work at the polished rod means more work at the plunger.", "The plunger stroke holds at 98.526653 in, since damping moves the loads and the power but not the travel."]'::jsonb, 1, 'Production falls from 353.253676 to 309.745554 bbl/d across the same rows, so the price of a barrel rises at both ends of the fraction at once.'),
  ('rodpump', 'intermediate', 'final', null, 36, 'Between 6.0 and 12.0 spm the ODUMA-4 horsepower climbs steadily while the plunger stroke ladder on the published taper steps back twice inside four rows. What does that pair say?', '["The horsepower is the converged quantity and the plunger stroke is not, since only one of the two is smooth.", "The two are read off different samplings, so one is smooth and the other ragged.", "The stroke ladder is noise and the horsepower is signal, since a card area integrates the noise away.", "Smoothness in an input belongs to a named quantity and not to the solver that produced it."]'::jsonb, 3, 'The peak polished rod load climbs without a step back over the same speeds on which the plunger stroke steps back six times, out of one march.'),
  ('rodpump', 'intermediate', 'final', null, 37, 'The ODUMA-4 card reads 11533.363199291 lb at cycle fraction 0.680524 and 5886.860579584 lb at 0.756137, with the reported minimum of 2625.472705679 lb between them. What is happening there?', '["The load transfer, where the card falls and recovers thousands of pounds inside a couple of the points that were kept.", "The pound down, where the plunger travels through the empty part of the barrel at a fillage of 0.9 with the fluid load still standing on it.", "The counterbalance handing work back to the gearbox, which is the only place on a surface card where a load falls that far that fast.", "The polished rod passing the bottom of its travel, where the four-bar velocity changes sign."]'::jsonb, 0, 'It is the narrowest and the fastest moving part of the loop, which is why the minimum is the extreme a card of 186 points is least likely to land on.'),
  ('rodpump', 'intermediate', 'final', null, 38, 'ODUMA-4 reports 0.059879964 hp per bbl/d at the shipped defaults. What is that ratio good for?', '["One design at one speed, since it is a mechanical rate at one named point in the machine.", "Pricing a barrel, once a tariff and a motor efficiency are applied outside the engine.", "Comparing designs, since it collects the power and the production into the one figure a design sheet needs.", "Bounding the meter, since the polished rod is the last point the work can be measured."]'::jsonb, 0, 'Walking the damping ratio alone takes the horsepower from 15.588073 to 24.404568 hp while production falls from 353.253676 to 309.745554 bbl/d, so the ratio moves with an input nobody measures.'),
  ('rodpump', 'intermediate', 'final', null, 39, 'At 0.5 spm the wave crosses the published taper 195.465131814 times in one stroke and the march returns 45.286791250 in against a spring rule of 45.279814701 in. Why do those two facts belong together?', '["The march has not converged at that speed, so it returns the closed form it was seeded with.", "A string the wave crosses two hundred times a stroke is behaving as a spring, and a spring is what the closed form describes.", "The crossings set the time step, so a slow row is marched finely enough to reproduce a closed form exactly.", "The spring rule is evaluated inside the march at low speed and returned in place of the marched answer."]'::jsonb, 1, 'At 9 spm the same string makes 10.859173990 round trips per stroke and the two answers separate by 9.696181 percent.'),
  ('rodpump', 'intermediate', 'final', null, 40, 'Changing the ODUMA-4 fillage from 1.0000 to 0.9000 changes the plunger stroke from 95.508351 in to 98.526653 in. Why is the resulting design not the same machine making less oil?', '["The fillage scaled the swept volume after the march, so only the rates moved and the card is the same loop.", "The fillage shortened the surface stroke the four-bar delivers, which is how a partly filled barrel reaches the surface.", "The fillage scaled the fluid load, so the loads moved while the plunger travel stayed where a full barrel put it.", "The fillage went into the march through the pound down state, so the card and the load transfer moved with it."]'::jsonb, 3, 'The fluid load stays on the plunger while it travels down through the empty part of the barrel, and that travel is inside the reported plunger stroke.'),
  ('rodpump', 'intermediate', 'final', null, 41, 'The order of work says to read the two loads together and against the rod weight. On the published taper at 9 spm, what does that reading give?', '["A load range of 10667.390282828 lb, which is the only figure that carries both ends of the card at once.", "A peak of 16490.601223 lb against a structural rating, and a minimum of 5823.210940 lb against zero.", "A peak 7816.843261277 lb above and a minimum 2850.547021552 lb below a buoyed weight of 8673.757961783 lb.", "The two groups F1 over Skr and F2 over Skr, which are the two loads written on the load scale of the string."]'::jsonb, 2, 'The distance from the static datum is what the word dynamic means here, and neither load carries it alone.'),
  ('rodpump', 'intermediate', 'final', null, 42, 'The default card on the published taper gives up 416.1138 in-lb per cycle of area at 9 spm and 63.3284 in-lb per cycle at 5 spm. What follows for the horsepower?', '["It is only as good as the loop it was handed, and the same default costs 0.128494 percent at one speed and 0.023711 percent at the other.", "It is unaffected, since the area lost by decimation is the same fraction on every card and cancels in the ratio.", "It should be corrected upward by the larger of the two, since a decimated loop always understates a card area.", "It is inside the published gates either way, so the loss is invisible to any check the engine makes."]'::jsonb, 0, 'Same default and same string, and one run costs several times the other, because how much a coarse loop loses depends on how sharply the real card turns.');
